package com.rpb.reservation.workforce.attendance.daily;
import static com.rpb.reservation.workforce.attendance.daily.AttendanceDailyDtos.*;import com.rpb.reservation.workforce.application.WorkforceJson;import java.sql.*;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class AttendanceDailyRepository {
 private final JdbcTemplate jdbc;private final WorkforceJson json;
 public AttendanceDailyRepository(JdbcTemplate jdbc,WorkforceJson json){this.jdbc=jdbc;this.json=json;}
 public boolean headOfficeReviewer(UUID tenant,UUID account){if(account==null)return false;return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from auth_accounts a where a.tenant_id=? and a.id=? and exists(select 1 from auth_account_roles r where r.account_id=a.id and r.deleted_at is null and r.role_code='tenant_admin') and not exists(select 1 from auth_account_roles r where r.account_id=a.id and r.deleted_at is null and r.role_code in ('store_manager','platform_admin')) and exists(select 1 from auth_account_permissions p where p.account_id=a.id and p.deleted_at is null and p.permission_code='tenant.admin.manage') and exists(select 1 from auth_account_permissions p where p.account_id=a.id and p.deleted_at is null and p.permission_code='workforce.admin.manage'))",Boolean.class,tenant,account));}
 public List<UUID> actualOverlaps(UUID tenant,UUID company,UUID employee,UUID session,Instant from,Instant to){return jdbc.queryForList("select a.id from workforce_attendance_sessions a join workforce_schedules s on s.tenant_id=a.tenant_id and s.id=a.schedule_id where a.tenant_id=? and a.employee_id=? and s.company_id=? and s.deleted_at is null and s.status='scheduled' and a.id<>? and a.in_at<? and (a.out_at is null or a.out_at>?) order by a.id",UUID.class,tenant,employee,company,session,Timestamp.from(to),Timestamp.from(from));}
 public List<com.rpb.reservation.workforce.calendar.CalendarDtos.CalendarEvent> calendar(UUID tenant,UUID store,LocalDate date){return new com.rpb.reservation.workforce.calendar.CalendarRepository(jdbc).list(tenant,store,date,date);}
 public List<com.rpb.reservation.workforce.scheduling.restswap.RestSwapDtos.Link> restSwaps(UUID tenant,UUID store,UUID employee,LocalDate date){return new com.rpb.reservation.workforce.calendar.CalendarRepository(jdbc).restSwaps(tenant,store,date,date,employee);}
 public Optional<EffectiveDay> latest(UUID tenant,UUID company,UUID employee,LocalDate date){return jdbc.query("select v.snapshot from workforce_attendance_days d join workforce_attendance_day_versions v on v.tenant_id=d.tenant_id and v.day_id=d.id where d.tenant_id=? and d.company_id=? and d.employee_id=? and d.work_date=? order by v.version desc limit 1",(r,n)->json.read(r.getString(1),EffectiveDay.class),tenant,company,employee,date).stream().findFirst();}
 public void save(UUID tenant,UUID company,UUID employee,UUID actor,EffectiveDay day){jdbc.update("insert into workforce_attendance_days(id,tenant_id,company_id,employee_id,work_date) values(?,?,?,?,?) on conflict(tenant_id,company_id,employee_id,work_date) do nothing",day.sourceId(),tenant,company,employee,day.workDate());jdbc.update("insert into workforce_attendance_day_versions(tenant_id,day_id,version,source_fingerprint,mode,state,snapshot,actor_id) values(?,?,?,?,?,?,?::jsonb,?)",tenant,day.sourceId(),day.version(),day.sourceFingerprint(),day.mode(),day.state(),json.write(day),actor);}
 public List<UUID> companyEmployees(UUID tenant,UUID company,LocalDate from,LocalDate to){return jdbc.queryForList("select e.id from workforce_employees e where e.tenant_id=? and e.hire_date<=? and (e.leave_date is null or e.leave_date>=?) and exists(select 1 from (select h.company_id,h.effective_date,coalesce(lead(h.effective_date) over(order by h.effective_date,h.version),date '9999-12-31') next_date from workforce_company_history h where h.tenant_id=e.tenant_id and h.employee_id=e.id) h where h.company_id=? and h.effective_date<=? and h.next_date>?) order by e.employee_no,e.id limit 501",UUID.class,tenant,to,from,company,to,from);}
 public List<UUID> employees(UUID tenant,UUID store,LocalDate from,LocalDate to){return jdbc.queryForList("select e.id from workforce_employees e where e.tenant_id=? and e.hire_date<=? and (e.leave_date is null or e.leave_date>=?) and exists(select 1 from workforce_work_stores w where w.tenant_id=e.tenant_id and w.employee_id=e.id and w.store_id=? and w.started_on<=? and (w.ended_on is null or w.ended_on>?)) order by e.employee_no,e.id",UUID.class,tenant,to,from,store,to,from);}
 public List<IntervalException> exceptions(UUID tenant,UUID company,UUID employee,LocalDate from,LocalDate to){return jdbc.query("select * from workforce_attendance_exceptions where tenant_id=? and company_id=? and employee_id=? and work_date between ? and ? order by start_at,id",this::read,tenant,company,employee,from,to);}
 public Optional<IntervalException> exception(UUID tenant,UUID id){return jdbc.query("select * from workforce_attendance_exceptions where tenant_id=? and id=?",this::read,tenant,id).stream().findFirst();}
 private IntervalException read(ResultSet r,int n)throws SQLException{return new IntervalException(r.getObject("id",UUID.class),r.getObject("employee_id",UUID.class),r.getObject("company_id",UUID.class),r.getObject("store_id",UUID.class),r.getObject("work_date",LocalDate.class),r.getString("kind"),r.getObject("type_id",UUID.class),r.getString("type_name"),r.getBoolean("paid"),r.getTimestamp("start_at").toInstant(),r.getTimestamp("end_at").toInstant(),r.getString("reason"),r.getString("status"),r.getObject("applicant_id",UUID.class),r.getObject("reviewer_id",UUID.class),r.getString("review_note"),r.getString("last_action"),r.getLong("version"),r.getTimestamp("created_at").toInstant(),r.getString("medical_reference"));}
 public void create(UUID tenant,IntervalException e){jdbc.update("insert into workforce_attendance_exceptions(id,tenant_id,company_id,employee_id,store_id,work_date,kind,type_id,type_name,paid,start_at,end_at,reason,status,applicant_id,version,created_at,medical_reference) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",e.id(),tenant,e.companyId(),e.employeeId(),e.storeId(),e.workDate(),e.kind(),e.typeId(),e.typeName(),e.paid(),Timestamp.from(e.startAt()),Timestamp.from(e.endAt()),e.reason(),e.status(),e.applicantId(),e.version(),Timestamp.from(e.createdAt()),e.medicalReference());}
 public void decide(UUID tenant,UUID id,String status,String action,UUID actor,String note,long version){jdbc.update("update workforce_attendance_exceptions set status=?,last_action=?,reviewer_id=?,review_note=?,version=?,updated_at=now() where tenant_id=? and id=?",status,action,actor,note,version,tenant,id);}
 public boolean overlaps(UUID tenant,UUID employee,UUID except,Instant from,Instant to){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from workforce_attendance_exceptions where tenant_id=? and employee_id=? and id<>? and status in ('pending','approved','cancel_requested') and start_at<? and end_at>?) or exists(select 1 from workforce_leaves where tenant_id=? and employee_id=? and status in ('pending','approved','cancel_requested') and start_at<? and end_at>?)",Boolean.class,tenant,employee,except,Timestamp.from(to),Timestamp.from(from),tenant,employee,Timestamp.from(to),Timestamp.from(from)));}
}
